export const BODY: string = "\n<p>ہر ڈیزائنر نے اسکرین پر رنگ دیکھا ہے اور اس کا بالکل کوڈ چاہا ہے۔ اسکرین شاٹ، تصویر، لوگو، یا ویب سائٹ موک اپ میں مکمل رنگ ہو سکتا ہے، مگر اس کی قیمت کا اندازہ لگانا کبھی کام نہیں کرتا۔</p>\n<p>تصویر رنگ پکر اس مسئلے کو سیکنڈوں میں حل کرتا ہے۔ آپ تصویر کھولتے ہیں، کسی بھی پکسل کی طرف اشارہ کرتے ہیں، اور اس کا بالکل رنگ کوڈ HEX، RGB، HSL اور CMYK میں پڑھتے ہیں۔</p>\n<p>یہ رہنما بتاتا ہے کہ CompressMyPic تصویر رنگ پکر کیسے کام کرتا ہے، ہر رنگ کوڈ کا مطلب کیا ہے، اور چنے ہوئے رنگ کو حقیقی ڈیزائن اور ترقیاتی کام میں کیسے استعمال کریں۔</p>\n<h2 id=\"what-is-an-image-color-picker\">تصویر رنگ پکر کیا ہے؟</h2>\n<p>تصویر رنگ پکر براؤزر ٹول ہے جو آپ کی اپ لوڈ شدہ تصویر کے اندر کسی بھی پکسل کا رنگ پڑھتا ہے۔ یہ ڈیزائن پروگرام میں آئی ڈراپر ٹول کی طرح کام کرتا ہے، مگر کچھ انسٹال کیے بغیر۔</p>\n<p>آپ ٹول میں تصویر یا اسکرین شاٹ ڈالتے ہیں، اپنا کرسر تصویر پر منتقل کرتے ہیں، اور ٹول اس بالکل نقطے کے نیچے رنگ دکھاتا ہے۔ قیمت آپ کے منتقل ہوتے ہوئے براہ راست اپ ڈیٹ ہوتی ہے۔</p>\n<p>ٹول عام تصویر فارمیٹ قبول کرتا ہے جیسے JPG، PNG، WebP اور GIF۔ 20 MB تک فائلیں سپورٹ ہیں، جو تقریباً ہر تصویر، لوگو اور اسکرین شاٹ کو پورا کرتی ہیں جنہیں آپ کو نمونہ لینا ہو۔</p>\n<h2 id=\"how-the-eyedropper-reads-a-pixel\">آئی ڈراپر پکسل کیسے پڑھتا ہے</h2>\n<p>ہر ڈیجیٹل تصویر پکسل نامی چھوٹے مربعوں کا گرڈ ہے۔ ہر پکسل ایک رنگ محفوظ کرتا ہے، سرخ، سبز اور نیلی روشنی کے لیے تین اعداد سے بیان شدہ۔</p>\n<p>جب آپ تصویر پر کسی نقطے پر کلک کرتے ہیں تو ٹول اس ایک پکسل کی سرخ، سبز اور نیلی قیمتیں پڑھتا ہے۔ پھر وہ ان تین اعداد کو ہر رنگ فارمیٹ میں بدل دیتا ہے جس کی آپ کو ضرورت ہو سکتی ہے۔</p>\n<p>پڑھنے بالکل درست ہے، اندازہ نہیں۔ پکسل واقعی وہ رنگ ہے، اور آپ کا کاپی شدہ کوڈ اسے ڈیزائن فائل، اسٹائل شیٹ یا پرنٹ دستاویز میں وفاداری سے دوبارہ بنائے گا۔</p>\n<h2 id=\"color-codes-explained\">رنگ کوڈ جو آپ کو ملتے ہیں: HEX، RGB، HSL، CMYK</h2>\n<p>ہر چنا ہوا پکسل ایک ساتھ کئی رنگ کوڈ بناتا ہے۔ HEX چھ ہندسوں والا کوڈ ہے جو ویب ڈویلپر CSS میں استعمال کرتے ہیں، جیسے مضبوط نیلے کے لیے #2563EB۔</p>\n<p>RGB اسی رنگ کو 0 سے 255 تک تین اعداد کے طور پر بیان کرتا ہے، سرخ، سبز اور نیلے کے لیے ایک ایک۔ یہ وہ فارمیٹ ہے جسے زیادہ تر ڈیزائن ٹول اور تصویر ایڈیٹر مقامی طور پر سمجھتے ہیں۔</p>\n<p>HSL رنگ کو رنگت، سنترپتی اور روشنی سے بیان کرتا ہے۔ ڈیزائنر اسے پسند کرتے ہیں کیونکہ یہ لوگوں کے رنگ کے بارے میں سوچنے سے میل کھاتا ہے: رنگت چنیں، پھر اسے بھرپور یا ہلکا بنائیں۔</p>\n<h2 id=\"the-11x11-loupe\">11x11 لوپ: بڑا کرنا کیوں اہم ہے</h2>\n<p>عام زوم پر درست پکسل چننا مشکل ہے۔ پتلی لکیر، چھوٹا آئیکن، یا ایک پکسل سرحد بال کے فرق سے چھوٹنا آسان ہے، اور چھوٹنے سے غلط رنگ ملتا ہے۔</p>\n<p>ٹول اسے 11 بہ 11 میگنفائی شدہ لوپ سے حل کرتا ہے۔ یہ آپ کے کرسر کے گرد پکسل کا زوم شدہ منظر دکھاتا ہے، تاکہ آپ بالکل دیکھ سکیں کہ آپ کس پکسل کا نمونہ لینے والے ہیں۔</p>\n<p>لوپ UI اسکرین شاٹ کے لیے خاص طور پر مفید ہے۔ بٹن، تقسیم کرنے والے اور متن اکثر اینٹی ایلیاس کناروں پر بیٹھتے ہیں جہاں رنگ دو یا تین پکسل میں ملتا ہے۔</p>\n<h2 id=\"picked-swatches\">چنے ہوئے سویچ: مجموعہ بنانا</h2>\n<p>ایک رنگ شاذ ہی کافی ہوتا ہے۔ برانڈ پیلیٹ، ویب سائٹ تھیم، یا سلائیڈ ڈیک کو کئی رنگ چاہییں جو ایک ساتھ کام کریں، اور ٹول آپ کو انہیں ایک ایک کر کے جمع کرنے دیتا ہے۔</p>\n<p>ہر کلک نمونہ شدہ رنگ کو آپ کی Picked Swatches ٹرے میں شامل کرتا ہے۔ آپ اسی تصویر سے اہم رنگ، ایکسنٹ، پس منظر اور متن رنگ جمع کر سکتے ہیں۔</p>\n<p>سویچ کام کرتے ہوئے نظر آتے ہیں، اس لیے آپ انہیں ساتھ ساتھ موازنہ کر سکتے ہیں۔ اگر دو چن تقریباً ایک جیسے لگیں تو آپ ایک ہٹا سکتے ہیں اور صاف ورژن رکھ سکتے ہیں۔</p>\n<h2 id=\"export-css\">CSS برآمد کریں: تصویر سے اسٹائل شیٹ تک</h2>\n<p>جمع شدہ سویچ صرف تب مفید ہیں جب آپ انہیں اپنے پراجیکٹ میں لے جا سکیں۔ Export CSS بٹن آپ کے چنے ہوئے رنگ کو تیار CSS کسٹم پراپرٹی کے طور پر ڈاؤن لوڈ کرتا ہے۔</p>\n<p>ڈاؤن لوڈ آپ کو --color-1، --color-2، وغیرہ جیسے متغیر دیتا ہے، ہر ایک میں HEX قیمت ہے۔ آپ انہیں اسٹائل شیٹ میں چسپاں کر سکتے ہیں اور اپنے ڈیزائن میں کہیں بھی ان کا حوالہ دے سکتے ہیں۔</p>\n<p>یہ کوڈ ایک ایک کر کے متن فائل میں کاپی کرنے سے بہتر ہے۔ برآمد ہر رنگ کو ایک جگہ، درست ترتیب میں، بغیر نقل غلطیوں کے رکھتی ہے۔</p>\n<h2 id=\"picking-colors-from-photos\">تصویروں سے رنگ چننا</h2>\n<p>تصویریں چنے ہوئے رنگوں کا سب سے عام ماخذ ہیں۔ غروب آفتاب، مصنوعات شاٹ، یا سفر تصویر پوری پیلیٹ دے سکتی ہے جو پہلے سے ایک ساتھ قدرتی لگتی ہے۔</p>\n<p>تصویر کے سب سے بڑے چپٹے حصوں سے شروع کریں۔ صاف آسمان، رنگی دیوار، یا کپڑے کا ٹکڑا مستحکم رنگ دیتا ہے جو مصروف بناوٹ سے بہتر نمونہ برداشت کرتا ہے۔</p>\n<p>سب سے روشن جھلکیوں اور سب سے گہرے سائے سے بچیں۔ وہ حصے اکثر کٹے ہوتے ہیں، جس کا مطلب ہے کہ صحیح رنگ معلومات ضائع ہو گئی اور آپ کو ملنے والا کوڈ صرف سفید یا کالا ہے۔</p>\n<h2 id=\"picking-colors-from-logos-and-screenshots\">لوگو اور اسکرین شاٹ سے رنگ چننا</h2>\n<p>لوگو اور انٹرفیس اسکرین شاٹ درستگی کی صورت ہیں۔ برانڈ رنگ کو بالکل میل کھانا چاہیے، کیونکہ قریب رنگ اصلی لوگو کے ساتھ غلط لگتا ہے۔</p>\n<p>لوگو کے لیے بڑی چپٹی شکل کے درمیان کو نمونہ لیں۔ حرف یا بلاک کا مرکز ٹھوس ہوتا ہے، جبکہ کنارے پس منظر میں مل جاتے ہیں اور ملے ہوئے قیمت دیتے ہیں۔</p>\n<p>اسکرین شاٹ کے لیے جب ممکن ہو تو Ctrl+V سے سیدھا چسپاں کریں۔ ٹول کلپ بورڈ تصویریں قبول کرتا ہے، اس لیے آپ اسکرین پکڑ سکتے ہیں اور فائل محفوظ کیے بغیر اسے نمونہ لے سکتے ہیں۔</p>\n<h2 id=\"color-accuracy-jpeg-transparency\">رنگ درستگی: JPEG شور اور شفافیت</h2>\n<p>JPEG کمپریشن پکسل رنگوں کو تھوڑا بدلتی ہے۔ فارمیٹ رنگوں کو چھوٹے بلاک میں محفوظ کرتا ہے، اس لیے ہموار آسمان میں دو پڑوسی پکسل ایک یا دو ہندسوں سے مختلف ہو سکتے ہیں۔</p>\n<p>یہ تبدیلی زیادہ تر کام کے لیے عام اور بے ضرر ہے۔ وہ قیمت چنیں جو حصے میں سب سے زیادہ بار دکھائی دے، اور آپ کا نتیجہ آنکھ کو درست لگے گا۔</p>\n<p>PNG فائلیں مختلف برتاؤ کرتی ہیں۔ PNG بالکل رنگ محفوظ کرتا ہے، اس لیے آپ کا پڑھا کوڈ وہی کوڈ ہے جو فائل رکھتی ہے، بغیر کسی کمپریشن شور کے۔</p>\n<h2 id=\"picking-colors-on-mobile\">موبائل اور ٹچ اسکرین پر رنگ چننا</h2>\n<p>رنگ پکر فون اور ٹیبلٹ پر بھی کام کرتا ہے جیسے ڈیسک ٹاپ پر۔ آپ کلک کی بجائے تصویر پر ٹیپ کرتے ہیں، اور وہی لوپ اور سویچ خصوصیات لاگو ہوتی ہیں۔</p>\n<p>چھونا ماؤس سے کم درست ہے، کیونکہ انگلی ایک ساتھ کئی پکسل ڈھکتی ہے۔ میگنفائی شدہ لوپ یہاں اور بھی اہم ہے، کیونکہ یہ دکھاتا ہے کہ آپ کی انگلی کے نیچے کیا ہے۔</p>\n<p>اگر ہدف چھوٹا ہو تو ٹیپ کرنے سے پہلے اپنے براؤزر میں تصویر کو زوم کریں۔ بڑی تصویر آپ کی انگلی کو بڑا ہدف دیتی ہے اور پڑوسی پکسل نمونہ لینے کا موقع کم کرتی ہے۔</p>\n<h2 id=\"common-mistakes\">رنگ چنتے ہوئے عام غلطیاں</h2>\n<p>سب سے عام غلطی چپٹے حصے کی بجائے کنارہ نمونہ لینا ہے۔ اینٹی ایلیاس کنارے دو رنگ ملاتے ہیں، اور ملا ہوا قیمت ان میں سے کسی کا بھی نہیں ہے۔</p>\n<p>دوسری غلطی شور والی تصویر پر ایک کلک پر بھروسہ کرنا ہے۔ دانے دار تصویر میں ایک پکسل باہر والا ہو سکتا ہے، اس لیے ہمیشہ اسی جگہ کو دو یا تین بار نمونہ لیں۔</p>\n<p>لوگ یہ بھی بھول جاتے ہیں کہ اسکرینیں مختلف ہیں۔ ایک ہی HEX کوڈ دو مانیٹر پر تھوڑا مختلف لگ سکتا ہے، اس لیے رنگ کو اس کے کوڈ سے پرکھیں، صرف اس سے نہیں کہ وہ آپ کی ڈسپلے پر کیسا لگتا ہے۔</p>\n<h2 id=\"color-picker-vs-palette-extractor\">رنگ پکر بمقابلہ پیلیٹ ایکسٹریکٹر</h2>\n<p>رنگ پکر اور پیلیٹ ایکسٹریکٹر مختلف سوالات کا جواب دیتے ہیں۔ پکر آپ کو ایک پکسل کا بالکل رنگ بتاتا ہے جسے آپ چنتے ہیں، جبکہ ایکسٹریکٹر پوری تصویر کے غالب رنگ ڈھونڈتا ہے۔</p>\n<p>جب آپ جان لیں کہ آپ کو کیا چاہیے تو پکر استعمال کریں: لوگو کا بالکل نیلا، بٹن کا بالکل رنگ، یا تصویر میں دیوار کا بالکل لہجہ۔</p>\n<p>جب آپ کو خیالات چاہییں تو ایکسٹریکٹر استعمال کریں: وہ پانچ یا چھ رنگ جو تصویر کو طے کرتے ہیں، تصویر کا کتنا حصہ ڈھکنے کے حساب سے درجہ بند۔ یہ مکمل پیلیٹ کا تیز راستہ ہے۔</p>\n<h2 id=\"who-uses-a-color-picker\">تصویر رنگ پکر کون استعمال کرتا ہے؟</h2>\n<p>ویب ڈویلپر اسے ڈیزائن موک اپ سے بالکل میل کھانے کے لیے استعمال کرتے ہیں۔ جب کلائنٹ ڈیزائن فائل کی بجائے اسکرین شاٹ بھیجے تو پکر حقیقی HEX کوڈ واپس لاتا ہے۔</p>\n<p>گرافک ڈیزائنر اسے حوالہ تصویروں سے پیلیٹ بنانے کے لیے استعمال کرتے ہیں۔ موڈ بورڈ تصویر پوسٹر یا برانڈ شناخت کے لیے پوری رنگ اسکیم دے سکتی ہے۔</p>\n<p>پرنٹ ڈیزائنر CMYK پڑھنے کو نقطہ آغاز کے طور پر استعمال کرتے ہیں۔ یہ مکمل پرنٹ میل نہیں، مگر یہ بتاتا ہے کہ روشن اسکرین رنگ کاغذ پر بچے گا یا نہیں۔</p>\n<h2 id=\"privacy-in-your-browser\">رازداری: آپ کی تصویریں آپ کے براؤزر میں رہتی ہیں</h2>\n<p>رازداری اہم ہے جب تصویر کلائنٹ موک اپ، غیر جاری شدہ مصنوعات شاٹ، یا ذاتی تصویر ہو۔ ایسی فائلیں بے ترتیب سرور پر اپ لوڈ کرنا ایسا خطرہ ہے جو آپ کو لینے کی ضرورت نہیں۔</p>\n<p>یہ ٹول سب کچھ مقامی طور پر پروسیس کرتا ہے۔ تصویر آپ کے براؤزر سے پڑھی جاتی ہے، پکسل آپ کے آلے پر نمونہ لیے جاتے ہیں، اور کچھ بھی آپ کے کمپیوٹر سے نہیں جاتا۔</p>\n<p>اس کا مطلب یہ بھی ہے کہ صفحہ لوڈ ہونے کے بعد ٹول آف لائن کام کرتا ہے۔ آپ ہوائی جہاز پر، میٹنگ روم میں، یا کنکشن کے بغیر کہیں بھی رنگ نمونہ لے سکتے ہیں۔</p>\n<h2 id=\"sampling-gradients-and-patterns\">گریڈینٹ اور نمونوں سے رنگ نمونہ لینا</h2>\n<p>گریڈینٹ خاص صورت ہیں، کیونکہ رنگ ایک سرے سے دوسرے تک ہموار بدلتا ہے۔ گریڈینٹ میں کوئی ایک درست رنگ نہیں، صرف وہ رنگ جو آپ کے نمونہ لینے والے بالکل نقطے پر ہے۔</p>\n<p>گریڈینٹ پکڑنے کے لیے اس کی لمبائی کے ساتھ کئی نقطے نمونہ لیں۔ شروع رنگ، درمیان رنگ، اور آخر رنگ چنیں، اور آپ ان تین سٹاپ سے CSS میں گریڈینٹ دوبارہ بنا سکتے ہیں۔</p>\n<p>نمونوں کو اسی احتیاط کی ضرورت ہے۔ دھاری دار یا چیکر سطح میں کم از کم دو رنگ ہوتے ہیں، اور پکر صرف آپ کے کرسر کے نیچے پکسل پڑھتا ہے، نمونہ کو مجموعی طور پر نہیں۔</p>\n<h2 id=\"how-to-use-the-tool\">تصویر رنگ پکر کیسے استعمال کریں</h2>\n<p>اپنے براؤزر میں <a href=\"/ur/tasveer-se-rang-chunein/\">تصویر رنگ پکر</a> کھولیں۔ اپنی تصویر اپ لوڈ والے حصے میں گھسیٹ دیں، یا کلپ بورڈ سے اسکرین شاٹ سیدھا چسپاں کریں۔</p>\n<p>جیسے ہی تصویر لوڈ ہوتی ہے، پہلے سے طے شدہ رنگ دکھائی دیتا ہے، تصویر کے مرکز سے نمونہ لیا گیا۔ اپنا کرسر منتقل کر کے دریافت کریں، اور لوپ کو اپنے پوائنٹر کے نیچے پکسل میں زوم کرتے دیکھیں۔</p>\n<p>اپنے Picked Swatches میں شامل کرنے کے لیے کسی بھی پکسل پر کلک کریں۔ اپنے ڈیزائن کے لیے چاہیے رنگوں کا مکمل سیٹ جمع کرنے کے لیے کلک کرتے رہیں۔</p>\n<p>جب آپ کا مجموعہ مکمل ہو تو رنگوں کو اسٹائل شیٹ متغیر کے طور پر ڈاؤن لوڈ کرنے کے لیے Export CSS پر کلک کریں۔ پھر قدم بہ قدم ورژن <a href=\"/ur/blog/tasveer-se-rang-kaise-chunein/\">How to Pick a Color from an Image</a> میں پڑھیں، یا کوڈ فارمیٹ <a href=\"/ur/blog/hex-vs-rgb-vs-hsl/\">HEX vs RGB vs HSL: Colour Codes Explained</a> میں سیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"رنگ چننے اور پیلیٹ نکالنے میں کیا فرق ہے؟","answer":"چننا ایک بالکل پکسل پڑھتا ہے جسے آپ چنتے ہیں، اس لیے آپ بالکل کنٹرول کرتے ہیں کہ آپ کو کون سا رنگ ملتا ہے۔ نکالنا پوری تصویر اسکین کرتا ہے اور اس کے سب سے عام رنگ خود بخود درجہ دیتا ہے۔ برانڈ کے بالکل رنگوں کے لیے پکر استعمال کریں اور تصویر سے تیار پیلیٹ چاہنے پر ایکسٹریکٹر استعمال کریں۔"},{"question":"ایک ہی حصے پر دو کلک تھوڑے مختلف HEX کوڈ کیوں دیتے ہیں؟","answer":"تصویروں میں پڑوسی پکسل شاذ ہی ایک جیسے ہوتے ہیں کیونکہ کیمرہ شور اور JPEG کمپریشن ہے۔ ہر پکسل اپنا رنگ رکھتا ہے، اس لیے ایک پکسل طرف منتقل کرنے سے آخری ہندسہ بدل سکتا ہے۔ چپٹے حصے کے درمیان کو نمونہ لیں اور وہ قیمت چنیں جو سب سے زیادہ بار دکھائی دے۔"},{"question":"کیا چنے ہوئے رنگ سیدھے ویب سائٹ اسٹائل شیٹ میں استعمال کر سکتا ہوں؟","answer":"جی ہاں۔ Export CSS بٹن آپ کے سویچ کو HEX قیمتوں والی CSS کسٹم پراپرٹی کے طور پر ڈاؤن لوڈ کرتا ہے۔ انہیں اپنی اسٹائل شیٹ میں چسپاں کریں اور متغیر کو کہیں بھی استعمال کریں جہاں آپ کو وہ رنگ چاہیے۔ HEX کوڈ کسی بھی ڈیزائن ٹول میں بھی کام کرتے ہیں جو چسپاں شدہ رنگ قیمتیں قبول کرے۔"},{"question":"کیا رنگ پکر میری تصویر بدلتا یا کمپریس کرتا ہے؟","answer":"نہیں۔ ٹول صرف پکسل قیمتیں پڑھتا ہے اور آپ کی فائل کو کبھی ترمیم، دوبارہ محفوظ، یا کمپریس نہیں کرتا۔ آپ کی اصل تصویر اچھوتی رہتی ہے، اور آپ صفحہ بند کر سکتے ہیں یہ جانتے ہوئے کہ آپ کے آلے پر فائل بالکل ویسی ہی ہے جیسی تھی۔"},{"question":"جس ویب سائٹ سے تصویر ڈاؤن لوڈ نہیں کر سکتا، اس سے رنگ کیسے چنوں؟","answer":"صفحے کا اسکرین شاٹ لیں، پھر اسے Ctrl+V سے ٹول میں چسپاں کریں یا اسکرین شاٹ فائل اپ لوڈ کریں۔ پکر اسکرین شاٹ پکسل کو کسی بھی دوسری تصویر کی طرح پڑھتا ہے، اس لیے آپ کسی بھی سائٹ سے بٹن، پس منظر اور متن رنگ نمونہ لے سکتے ہیں۔"},{"question":"اگر میرا چنا ہوا رنگ میرے ڈیزائن ٹول میں مختلف لگے تو کیا کروں؟","answer":"پہلے جانچیں کہ آپ نے مکمل HEX کوڈ کاپی کیا، کوئی ہندسہ گم کیے بغیر۔ پھر یاد رکھیں کہ مانیٹر اور رنگ پروفائل مختلف ہیں، اس لیے ایک ہی کوڈ دو اسکرین پر تھوڑا مختلف لگ سکتا ہے۔ خود کوڈ پر بھروسہ کریں، اور اسے اسی اسکرین پر اصل تصویر سے موازنہ کریں۔"}];
